const {chromium}=require('playwright');const fs=require('fs');const path=require('path');
(async()=>{const b=await chromium.launch({executablePath:process.env.CHROMIUM_PATH || '/usr/bin/chromium',args:['--no-sandbox']});const p=await b.newPage();const root=process.cwd();await p.route('https://ev.jworldcreations.com/**',async route=>{const pathname=new URL(route.request().url()).pathname;let file=path.join(root,pathname);try{const body=fs.readFileSync(file);await route.fulfill({body,contentType:file.endsWith('.js')||file.endsWith('.mjs')?'text/javascript':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':file.endsWith('.json')?'application/json':'application/octet-stream'});}catch{await route.fulfill({status:404,body:'Not found'})}});const errors=[];p.on('pageerror',e=>errors.push(e.message));for(const w of [360,768,1440]){await p.setViewportSize({width:w,height:900});await p.goto('https://ev.jworldcreations.com/ev-revival-local.html');await p.waitForFunction(()=>customElements.get('esp-web-install-button'));if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Overflow');await p.locator('#hardware-confirm').check();if(!await p.locator('#flash-button').isDisabled())throw Error('missing consent gate');await p.locator('#data-loss-confirm').check();if(await p.locator('#flash-button').isDisabled())throw Error('button disabled');if(await p.locator('select').count())throw Error('Mode/version dropdown remains');if(await p.locator('#help-details').getAttribute('open')!==null)throw Error('Help should start collapsed');await p.locator('a[href="#installation-help"]').last().click();if(await p.locator('#help-details').getAttribute('open')===null)throw Error('Help did not open');await p.locator('#data-loss-confirm').uncheck();const blocked=await p.evaluate(async()=>{try{const m=await(await fetch('ev-revival-local/manifest.json')).json();await window.evRevivalPolicy.prepare({chip:{CHIP_NAME:'ESP32'},getFlashSize:async()=>4096},m,true);return false}catch{return true}});if(!blocked)throw Error('Recovery bypassed consent');await p.locator('#data-loss-confirm').check();await p.evaluate(()=>window.evRevivalPolicy.status({state:'writing',details:{percentage:42}}));if(await p.locator('#install-progress').getAttribute('value')!=='42')throw Error('Progress missing');await p.evaluate(()=>window.evRevivalPolicy.status({state:'finished'}));if(!(await p.locator('#install-message').innerText()).includes('Installation complete'))throw Error('Success missing');await p.evaluate(()=>window.evRevivalPolicy.status({state:'error',message:'Connection failed'}));if(!(await p.locator('#install-message').innerText()).includes('Installation stopped'))throw Error('Failure missing');await p.screenshot({path:'/tmp/pr34-'+w+'.png',fullPage:true});console.log(w,'single install flow, confirmations, help/recovery and progress pass');}const result=await p.evaluate(async()=>{const m=await(await fetch('ev-revival-local/manifest.json')).json();const buffers=await window.evRevivalPolicy.prepare({chip:{CHIP_NAME:'ESP32'},getFlashSize:async()=>4096},m,false);return buffers[0].byteLength});console.log('browser Web Crypto verified actual pinned binary:',result);await p.route('**/*.bin',r=>r.fulfill({body:Buffer.alloc(10)}));const error=await p.evaluate(async()=>{try{const m=await(await fetch('ev-revival-local/manifest.json')).json();await window.evRevivalPolicy.prepare({chip:{CHIP_NAME:'ESP32'},getFlashSize:async()=>4096},m,false)}catch(e){return e.message}});if(!error?.includes('wrong size'))throw Error(error);console.log('truncated image stopped:',error);if(errors.length)throw Error(errors.join('\n'));await b.close()})();
